CREATE TABLE IF NOT EXISTS email_outbox (
  id bigserial PRIMARY KEY,
  dedupe_key text NOT NULL UNIQUE,
  to_email text NOT NULL,
  subject text NOT NULL,
  body_html text NOT NULL,
  body_text text NOT NULL,
  content_hash text NOT NULL,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sending', 'sent', 'retry', 'failed', 'stuck')),
  attempts int NOT NULL DEFAULT 0,
  next_attempt_at timestamptz NOT NULL DEFAULT now(),
  claimed_at timestamptz,
  last_error text,
  stuck_reported boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  sent_at timestamptz
);
CREATE INDEX IF NOT EXISTS email_outbox_due ON email_outbox (status, next_attempt_at);
CREATE TABLE IF NOT EXISTS email_suppression (
  email text PRIMARY KEY,
  reason text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE OR REPLACE FUNCTION email_outbox_enqueue(p_key text, p_to text, p_subject text, p_html text, p_text text)
RETURNS TABLE (outcome text, id bigint, status text, attempts int, sent_at timestamptz, same_content boolean, reason text)
LANGUAGE plpgsql AS $$
#variable_conflict use_column
DECLARE
  v_hash text := md5(p_to || chr(10) || p_subject || chr(10) || p_html || chr(10) || p_text);
  v_id bigint;
  v_reason text;
BEGIN
  -- Each statement sees rows committed a moment ago, so a twin request that won the race is found here.
  RETURN QUERY SELECT 'duplicate'::text, o.id, o.status, o.attempts, o.sent_at, o.content_hash = v_hash, NULL::text
    FROM email_outbox o WHERE o.dedupe_key = p_key;
  IF FOUND THEN RETURN; END IF;
  SELECT s.reason INTO v_reason FROM email_suppression s WHERE s.email = p_to;
  IF FOUND THEN
    RETURN QUERY SELECT 'suppressed'::text, NULL::bigint, NULL::text, NULL::int, NULL::timestamptz, NULL::boolean, v_reason;
    RETURN;
  END IF;
  INSERT INTO email_outbox (dedupe_key, to_email, subject, body_html, body_text, content_hash)
  VALUES (p_key, p_to, p_subject, p_html, p_text, v_hash)
  ON CONFLICT (dedupe_key) DO NOTHING
  RETURNING email_outbox.id INTO v_id;
  IF v_id IS NOT NULL THEN
    RETURN QUERY SELECT 'queued'::text, v_id, 'queued'::text, 0, NULL::timestamptz, true, NULL::text;
    RETURN;
  END IF;
  RETURN QUERY SELECT 'duplicate'::text, o.id, o.status, o.attempts, o.sent_at, o.content_hash = v_hash, NULL::text
    FROM email_outbox o WHERE o.dedupe_key = p_key;
END $$;

