// Server-side checks. Nothing reaches the database unless every field is valid.
const s = $input.first().json;
const b = s.body;
const fail = (error) => [{ json: { valid: false, error } }];
if (!b || typeof b !== 'object' || Array.isArray(b)) return fail('Send a JSON object with to, subject, html or text, and dedupe_key.');
const str = (v) => (typeof v === 'string' || typeof v === 'number') ? String(v).trim() : '';
const key = str(b.dedupe_key);
if (!key) return fail('"dedupe_key" is required, for example "invoice-123-reminder-1".');
if (key.length > 200 || !/^[\x21-\x7E]+$/.test(key)) return fail('"dedupe_key" must be 1-200 visible characters without spaces.');
const to = str(b.to).toLowerCase();
if (!to) return fail('"to" is required.');
if (to.length > 254 || !/^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/.test(to)) return fail('"to" must be one valid email address.');
const subject = str(b.subject);
if (!subject) return fail('"subject" is required.');
if (subject.length > 250 || /[\r\n]/.test(subject)) return fail('"subject" must be one line of at most 250 characters.');
let html = typeof b.html === 'string' ? b.html.trim() : '';
let text = typeof b.text === 'string' ? b.text.trim() : '';
if (!html && !text) return fail('Send "html" or "text" (or both) with some content.');
const max = Number(s.max_body_chars) || 200000;
if (html.length + text.length > max) return fail('The email body is longer than ' + max + ' characters.');
// Always send both parts: plain text from the HTML, or simple HTML from the text.
if (!text) text = html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|h[1-6]|li|tr)>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/\n{3,}/g, '\n\n').trim();
if (!html) html = '<p>' + text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>') + '</p>';
return [{ json: { valid: true, dedupe_key: key, to, subject, html, text } }];

