// Decide what an SMTP error means. Only errors where the server certainly did not take the email are retried.
const s = $('Outbox Settings').first().json;
const maxAttempts = Number(s.max_attempts) || 5;
const base = Number(s.retry_base_minutes) || 5;
return $input.all().map((item, i) => {
  const row = $('Claim Due Emails').itemMatching(i).json; // the claimed row this failed send belongs to (paired item)
  const error = String(item.json.error?.message || item.json.error || item.json.message || 'Unknown SMTP error').slice(0, 500);
  const m = error.match(/(?:^|:\s)([45])(\d\d)[\s-]/);
  const code = m ? Number(m[1] + m[2]) : null;
  // No connection, or no greeting yet: nothing can have been sent.
  const refused = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|Greeting never received/i.test(error);
  const loginFailed = [530, 534, 535].includes(code); // SMTP login refused: the email was never handed over
  let status, suppress = false, delay = 0;
  if ((code && code < 500) || loginFailed || (!code && refused)) {
    status = row.attempts < maxAttempts ? 'retry' : 'failed';
    delay = base * Math.pow(2, row.attempts - 1);
  } else if (code) {
    status = 'failed';
    // Block the address only when the server says the mailbox or domain does not exist (enhanced code 5.1.0-5.1.6 or 5.1.10).
    // Policy rejections such as "550 5.7.1 Relaying denied" or a blocklisted sender IP fail the email but block nothing.
    suppress = [550, 551, 553].includes(code) && /recipient/i.test(error) && /\b5\.1\.(?:[0-46]|10)\b/.test(error);
  } else {
    status = 'stuck'; // timeout, dropped connection, TLS error...: the email may or may not have arrived
  }
  return { json: { id: row.id, status, suppress, retry_in_minutes: delay, error: (status === 'stuck' ? 'outcome unknown, not resent: ' : '') + error } };
});

